"use client";

import { useEffect, useState, type ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { api } from "@/lib/api";

export type Task = { id: string; kind: string; status: string; message: string | null; result: Record<string, unknown> | null; created_at: string };
type Candidate = { id: string; document_id: string; content: string; category: string | null };
type Settings = { backup_dir: string; target_roles: string[]; weights: Record<string, number> };
type SheetConfig = { spreadsheet_id: string; tab: string; header_row: number; mapping: Record<string, string>; is_test_copy: boolean; sync_every_minutes: number };
type SheetStatus = { mode: "read_only" | "copy_status_write"; config: SheetConfig | null; connected: boolean; missing: string[]; last_sync: string | null };

function Field({ name, children }: { name: string; children: ReactNode }) { return <label className="field"><span>{name}</span>{children}</label>; }
function ErrorText({ error }: { error: Error | null }) { return error ? <p role="alert" className="error">{error.message}</p> : null; }

export function SheetSyncTime() {
  const query = useQuery({ queryKey: ["sheet-status"], queryFn: () => api<SheetStatus>("sheets/config") });
  return <p className="sync-time">Last Sheet sync: {query.data?.last_sync ? new Date(query.data.last_sync.endsWith("Z") || /[+-]\d\d:\d\d$/.test(query.data.last_sync) ? query.data.last_sync : query.data.last_sync + "Z").toLocaleString("en-GB", { timeZone: "Europe/London" }) : "Not synced yet"}</p>;
}

export function URLImport({ compact = false }: { compact?: boolean }) {
  const client = useQueryClient();
  const [url, setUrl] = useState("");
  const [html, setHtml] = useState("");
  const mutation = useMutation({ mutationFn: () => api<Task>("tasks/extract", "POST", { url, page_html: html }), onSuccess: () => { setUrl(""); setHtml(""); return client.invalidateQueries({ queryKey: ["tasks"] }); } });
  return <section className={compact ? "url-import compact-import" : "panel form-panel url-import"} aria-label="Paste a job URL">
    {!compact && <div className="panel-heading"><h2>Paste a job URL</h2><p className="muted small">Extract the listing in the background. Repeated URLs won’t create duplicate jobs.</p></div>}
    <form onSubmit={e => { e.preventDefault(); mutation.mutate(); }}>
      <div className="url-input-row"><label className="field"><span className={compact ? "sr-only" : ""}>Job listing URL</span><input type="url" required value={url} onChange={e => setUrl(e.target.value)} placeholder="Paste a job URL" /></label><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Adding…" : "Add job"}</Button></div>
      <details className="paste-source"><summary>Paste page HTML instead</summary><Field name="Public job page HTML"><textarea rows={4} maxLength={1000000} value={html} onChange={e => setHtml(e.target.value)} placeholder="Optional: paste the vacancy’s page HTML for local extraction." /></Field></details>
      <ErrorText error={mutation.error} />{mutation.isSuccess && <p className="success" role="status">Extraction queued. Follow its progress in Background tasks.</p>}
    </form>
  </section>;
}

export function TaskList({ onSelect }: { onSelect: (id: string) => void }) {
  const client = useQueryClient();
  const tasks = useQuery({ queryKey: ["tasks"], queryFn: () => api<Task[]>("tasks"), refetchInterval: 1500 });
  const fingerprint = tasks.data?.map(t => `${t.id}:${t.status}`).join(",");
  useEffect(() => {
    for (const key of ["jobs", "candidates", "documents", "sheet-status", "matches", "requirements", "sponsor-register"]) void client.invalidateQueries({ queryKey: [key] });
  }, [client, fingerprint]);
  const names: Record<string, string> = { extract_url: "Job URL extraction", parse_cv: "CV parsing", backup: "Backup and restore check", sheets_import: "Sheet import", sheets_sync: "Sheet sync", match_jobs: "Job matching", discover: "Job discovery", extract_requirements: "Local requirements extraction", import_sponsor_register: "Sponsor register import" };
  return <details className="panel disclosure task-panel"><summary>Background tasks<span className="summary-hint">{tasks.data?.filter(task => ["QUEUED", "RUNNING"].includes(task.status)).length ?? 0} running or queued</span></summary><div className="disclosure-content"><p className="small muted">Keep the app open while tasks finish. Interrupted tasks require review.</p><ErrorText error={tasks.error} /><div className="task-list">{tasks.data?.slice(0, 12).map(task => <article className="task-row" key={task.id}><div><strong>{names[task.kind] ?? task.kind}</strong><span className={`badge task-${task.status.toLowerCase()}`}>{task.status.toLowerCase().replaceAll("_", " ")}</span>{task.message && <p role={task.status === "FAILED" ? "alert" : "status"}>{task.message}</p>}{typeof task.result?.job_id === "string" && <Button variant="ghost" onClick={() => onSelect(String(task.result!.job_id))}>View job</Button>}{typeof task.result?.candidates === "number" && <p>{task.result.candidates} candidates ready for review in My Profile.</p>}{task.result?.restore_verified === true && <p>Backup restored and verified. {String(task.result.archive)}</p>}{typeof task.result?.matched === "number" && <p>{task.result.matched} scores calculated · {String(task.result.current ?? 0)} already current · {String(task.result.skipped ?? 0)} skipped</p>}{typeof task.result?.postings_read === "number" && <p>{task.result.postings_read} postings read · {String(task.result.jobs_created ?? 0)} jobs added · {String(task.result.duplicates ?? 0)} duplicates · {String(task.result.warnings ?? 0)} skipped/unusable rows</p>}{typeof task.result?.rows_preserved === "number" && <p>{task.result.rows_preserved} rows preserved · {String(task.result.cells_written ?? 0)} cells written · {String(task.result.warnings ?? 0)} warnings</p>}</div></article>)}{tasks.data?.length === 0 && <p className="muted">No tasks yet. Paste a job URL or upload a CV to begin.</p>}</div></div></details>;
}

export function CVReview() {
  const client = useQueryClient();
  const [file, setFile] = useState<File | null>(null);
  const [versionParent, setVersionParent] = useState("");
  const docs = useQuery({ queryKey: ["documents"], queryFn: () => api<{ id: string; format: string }[]>("documents") });
  const candidates = useQuery({ queryKey: ["candidates"], queryFn: () => api<Candidate[]>("candidates"), refetchInterval: 3000 });
  const upload = useMutation({ mutationFn: async () => {
    if (!file || file.size > 5000000) throw new Error("Choose a PDF, DOCX or TXT CV under 5 MB.");
    const format = file.name.split(".").pop()?.toLowerCase();
    if (!["pdf", "docx", "txt"].includes(format ?? "")) throw new Error("Choose a PDF, DOCX or TXT CV.");
    const content = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1]); reader.onerror = () => reject(new Error("The selected file could not be read.")); reader.readAsDataURL(file); });
    return api<Task>("documents", "POST", { format, content_base64: content, parent_id: versionParent || null });
  }, onSuccess: () => { void client.invalidateQueries({ queryKey: ["tasks"] }); void client.invalidateQueries({ queryKey: ["documents"] }); } });
  const download = useMutation({ mutationFn: async (document: { id: string; format: string }) => {
    const response = await fetch(`/api/documents/${document.id}/download`, { cache: "no-store" });
    if (!response.ok) throw new Error("The CV could not be downloaded.");
    const url = URL.createObjectURL(await response.blob()); const anchor = window.document.createElement("a"); anchor.href = url; anchor.download = `cv-${document.id}.${document.format}`; anchor.click(); URL.revokeObjectURL(url);
  } });
  return <section className="panel form-panel"><div className="panel-heading"><h2>Upload and review your CV</h2><p className="muted small">Parsing stays local. Suggested facts are copied from your document and need your review.</p></div><form onSubmit={e => { e.preventDefault(); upload.mutate(); }}><Field name="CV file"><input type="file" accept=".pdf,.docx,.txt" required onChange={e => setFile(e.target.files?.[0] ?? null)} /></Field><Field name="Previous CV version (optional)"><select value={versionParent} onChange={e => setVersionParent(e.target.value)}><option value="">New master document</option>{docs.data?.map(doc => <option key={doc.id} value={doc.id}>{doc.id}</option>)}</select></Field><Button type="submit" disabled={upload.isPending}>{upload.isPending ? "Uploading…" : "Upload CV for local parsing"}</Button><ErrorText error={upload.error} />{upload.isSuccess && <p className="success" role="status">CV queued for local parsing. Candidates will appear below.</p>}</form><div className="candidate-list"><ErrorText error={candidates.error ?? docs.error ?? download.error} />{docs.data?.map(doc => <Button key={doc.id} variant="ghost" onClick={() => download.mutate(doc)}>Download CV {doc.id.slice(0, 8)}</Button>)}{candidates.data?.map(candidate => <CandidateCard key={candidate.id} candidate={candidate} />)}</div></section>;
}

function CandidateCard({ candidate }: { candidate: Candidate }) {
  const client = useQueryClient();
  const [content, setContent] = useState(candidate.content);
  const [category, setCategory] = useState(candidate.category ?? "");
  const [confirmed, setConfirmed] = useState(false);
  const mutation = useMutation({ mutationFn: (reject: boolean) => api(`candidates/${candidate.id}/${reject ? "reject" : "accept"}`, "POST", reject ? undefined : { content, category, source: `CV document ${candidate.document_id}`, verified: confirmed }), onSuccess: () => { void client.invalidateQueries({ queryKey: ["candidates"] }); void client.invalidateQueries({ queryKey: ["facts"] }); } });
  return <article className="fact-card"><p className="small muted">Extracted candidate · {candidate.document_id.slice(0, 8)}</p><Field name="Candidate fact"><textarea rows={3} maxLength={10000} value={content} onChange={e => { setContent(e.target.value); setConfirmed(false); }} /></Field><Field name="Candidate category"><select value={category} onChange={e => { setCategory(e.target.value); setConfirmed(false); }}><option value="">Choose a category</option>{["education", "experience", "project", "skill"].map(c => <option key={c} value={c}>{c}</option>)}</select></Field><label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} />I have checked and confirm this exact fact.</label><ErrorText error={mutation.error} /><div className="form-actions"><Button variant="ghost" disabled={mutation.isPending} onClick={() => mutation.mutate(true)}>Discard candidate</Button><Button disabled={!category || !content.trim() || !confirmed || mutation.isPending} onClick={() => mutation.mutate(false)}>Save confirmed fact</Button></div></article>;
}

export function IntegrationSettings() {
  const preferences = useQuery({ queryKey: ["settings"], queryFn: () => api<Settings>("settings") });
  const sheet = useQuery({ queryKey: ["sheet-status"], queryFn: () => api<SheetStatus>("sheets/config") });
  return <div className="settings-grid">
    <div className="settings-stack"><details className="panel disclosure" open><summary>Backup and restore<span className="summary-hint">Keep a verified copy of your data</span></summary><div className="disclosure-content">{preferences.data && <PreferencesForm data={preferences.data} />}<ErrorText error={preferences.error} /></div></details>
    <details className="panel disclosure"><summary>Local access<span className="summary-hint">Dashboard opens directly</span></summary><div className="disclosure-content"><p className="muted">The dashboard opens directly on this computer. The API token stays in the local server’s private .env file and is never sent to the browser. Keep the app bound to localhost.</p></div></details></div>
    <div className="settings-stack">{preferences.data && <MatchingPreferences data={preferences.data} />}<DiscoverySettings /><SponsorRegisterSettings /><details className="panel disclosure" open><summary>Google Sheets<span className="summary-hint">Development copy only</span></summary><div className="disclosure-content"><p className="notice">The original tracker is blocked. Imports preserve your Sheet. Approved write-back changes individual status cells only.</p>{sheet.data && <SheetForm key={JSON.stringify(sheet.data.config)} status={sheet.data} />}<ErrorText error={sheet.error} /></div></details></div>
  </div>;
}

function PreferencesForm({ data }: { data: Settings }) {
  const client = useQueryClient();
  const [directory, setDirectory] = useState(data.backup_dir);
  const mutation = useMutation({ mutationFn: () => api("settings", "PUT", { ...data, backup_dir: directory, target_roles: data.target_roles }), onSuccess: () => client.invalidateQueries({ queryKey: ["settings"] }) });
  const backup = useMutation({ mutationFn: () => api<Task>("tasks/backup", "POST"), onSuccess: () => client.invalidateQueries({ queryKey: ["tasks"] }) });
  return <form onSubmit={e => { e.preventDefault(); mutation.mutate(); }}><Field name="Backup destination folder"><input value={directory} onChange={e => setDirectory(e.target.value)} placeholder="Absolute path outside storage" /></Field><p className="small muted">A daily backup runs while the app is open. Missed runs catch up once at startup. Each backup is restored and checked before success is reported. Keep your encryption key separately.</p><ErrorText error={mutation.error ?? backup.error} />{mutation.isSuccess && <p role="status" className="success">Settings saved.</p>}<div className="form-actions"><Button variant="outline" disabled={backup.isPending || !data.backup_dir} onClick={() => backup.mutate()}>Back up and verify restore</Button><Button type="submit" disabled={mutation.isPending}>Save settings</Button></div><details><summary>Restore a backup</summary><p className="small muted">From apps/api, use the restore command below with your chosen archive and a new destination folder. Restore never overwrites your active data.</p><code className="command-example">uv run python -m app.services.backup_cli restore --archive /path/backup.zip --destination /path/new-folder</code></details></form>;
}

function SheetForm({ status }: { status: SheetStatus }) {
  const client = useQueryClient();
  const [form, setForm] = useState<SheetConfig>(status.config ?? { spreadsheet_id: "", tab: "", header_row: 1, mapping: { company: "Company", deadline: "Deadline", url: "Application Link", status: "Status", notes: "Notes" }, is_test_copy: false, sync_every_minutes: 0 });
  const save = useMutation({ mutationFn: () => api("sheets/config", "PUT", form), onSuccess: () => client.invalidateQueries({ queryKey: ["sheet-status"] }) });
  const connect = useMutation({ mutationFn: () => api<{ url: string }>("sheets/oauth/start", "POST"), onSuccess: data => window.location.assign(data.url) });
  const run = useMutation({ mutationFn: (operation: string) => api<Task>(`tasks/sheets/${operation}`, "POST"), onSuccess: () => client.invalidateQueries({ queryKey: ["tasks"] }) });
  return <form onSubmit={e => { e.preventDefault(); save.mutate(); }}><p className="notice">{status.connected ? "Google is connected." : "Google is not connected."}{status.missing.length > 0 && ` Configure privately: ${status.missing.join(", ")}.`}</p><Field name="Test-copy spreadsheet ID"><input required value={form.spreadsheet_id} onChange={e => setForm({ ...form, spreadsheet_id: e.target.value })} /></Field><div className="form-grid"><Field name="Sheet tab name"><input required value={form.tab} onChange={e => setForm({ ...form, tab: e.target.value })} /></Field><Field name="Header row number"><input type="number" min={1} max={100} value={form.header_row} onChange={e => setForm({ ...form, header_row: Number(e.target.value) })} /></Field></div><h3>Column headers</h3>{Object.entries(form.mapping).map(([key, header]) => <Field key={key} name={`${key === "url" ? "Job URL" : key} header`}><input required value={header} onChange={e => setForm({ ...form, mapping: { ...form.mapping, [key]: e.target.value } })} /></Field>)}<Field name="Automatic read-only import interval (minutes, 0 disables)"><input type="number" min={0} max={1440} value={form.sync_every_minutes} onChange={e => setForm({ ...form, sync_every_minutes: Number(e.target.value) })} /></Field><label className="checkbox-label"><input type="checkbox" required checked={form.is_test_copy} onChange={e => setForm({ ...form, is_test_copy: e.target.checked })} />This is a separate test copy, not my original tracker.</label><ErrorText error={save.error ?? connect.error ?? run.error} /><div className="form-actions"><Button type="submit" disabled={save.isPending}>Save Sheet mapping</Button><Button variant="outline" disabled={connect.isPending || status.missing.length > 0} onClick={() => connect.mutate()}>Connect Google</Button></div><div className="form-actions"><Button variant="outline" disabled={!status.config || !status.connected || run.isPending} onClick={() => run.mutate("import")}>Import test copy</Button><Button variant="outline" disabled={status.mode !== "copy_status_write" || !status.config || !status.connected || run.isPending} onClick={() => run.mutate("sync")}>Write changed statuses to copy</Button><span className="small muted">{status.mode === "copy_status_write" ? "Status cells only. Reconnect Google after enabling write access. Notes, formulas and other cells are preserved." : "Read-only. Status write-back requires the approved copy ID in private server configuration."}</span></div></form>;
}

export function Declarations() {
  const client = useQueryClient();
  const [category, setCategory] = useState("right_to_work");
  const [question, setQuestion] = useState(""); const [value, setValue] = useState(""); const [confirmed, setConfirmed] = useState(false);
  const records = useQuery({ queryKey: ["declarations"], queryFn: () => api<{ id: string; question: string; value: string }[]>("declarations") });
  const save = useMutation({ mutationFn: () => api("declarations", "POST", { category, question, value, confirmed }), onSuccess: () => { setQuestion(""); setValue(""); setConfirmed(false); return client.invalidateQueries({ queryKey: ["declarations"] }); } });
  const remove = useMutation({ mutationFn: (id: string) => api(`declarations/${id}`, "DELETE"), onSuccess: () => client.invalidateQueries({ queryKey: ["declarations"] }) });
  return <section className="panel form-panel"><div className="panel-heading"><h2>Fixed declarations</h2><p className="muted small">Optional owner-confirmed answers only. No AI drafts or infers these values. Unknown answers remain unknown.</p></div><form onSubmit={e => { e.preventDefault(); save.mutate(); }}><Field name="Declaration category"><select value={category} onChange={e => { setCategory(e.target.value); setConfirmed(false); }}>{["right_to_work", "sponsorship", "convictions", "disability", "diversity", "consent", "identity"].map(c => <option key={c} value={c}>{c.replaceAll("_", " ")}</option>)}</select></Field><Field name="Exact question"><input required maxLength={500} value={question} onChange={e => { setQuestion(e.target.value); setConfirmed(false); }} /></Field><Field name="Your fixed answer"><textarea required maxLength={2000} value={value} onChange={e => { setValue(e.target.value); setConfirmed(false); }} /></Field><label className="checkbox-label"><input type="checkbox" required checked={confirmed} onChange={e => setConfirmed(e.target.checked)} />I confirm this answer for this exact question.</label><Button type="submit" disabled={!confirmed || save.isPending}>Save confirmed declaration</Button><ErrorText error={save.error ?? records.error ?? remove.error} /></form><div className="candidate-list">{records.data?.map(record => <article className="fact-card" key={record.id}><strong>{record.question}</strong><p className="preserve">{record.value}</p><Button variant="ghost" disabled={remove.isPending} onClick={() => { if (window.confirm("Delete this fixed declaration?")) remove.mutate(record.id); }}>Delete declaration</Button></article>)}</div></section>;
}


type DiscoverySource = { id: string; provider: string; board: string; employer: string; region: string; search_query: string; credentials_configured: boolean; enabled: boolean };
function DiscoverySettings() {
  const client = useQueryClient();
  const [board, setBoard] = useState("");
  const [query, setQuery] = useState("");
  const [provider, setProvider] = useState("greenhouse");
  const [employer, setEmployer] = useState("");
  const [region, setRegion] = useState("global");
  const [enabled, setEnabled] = useState(false);
  const sources = useQuery({ queryKey: ["discovery"], queryFn: () => api<DiscoverySource[]>("discovery") });
  const save = useMutation({ mutationFn: () => api("discovery", "POST", { board, enabled, provider, employer, region, search_query: query }), onSuccess: () => { setBoard(""); setQuery(""); setEmployer(""); setEnabled(false); return client.invalidateQueries({ queryKey: ["discovery"] }); } });
  const remove = useMutation({ mutationFn: (id: string) => api(`discovery/${id}`, "DELETE"), onSuccess: () => client.invalidateQueries({ queryKey: ["discovery"] }) });
  const run = useMutation({ mutationFn: (id: string) => api("tasks/discover", "POST", { source_id: id }), onSuccess: () => client.invalidateQueries({ queryKey: ["tasks"] }) });
  return <details className="panel disclosure"><summary>Job discovery<span className="summary-hint">Public boards and Reed search</span></summary><div className="disclosure-content"><p className="small">Import published jobs from a chosen employer’s public board. Greenhouse, Lever and Ashby read the selected board. SmartRecruiters and Reed import the first 20 postings with detailed API text; these bounded pages do not cover all results. Use preference scores to prioritise UK roles afterwards. Sponsorship does not exclude jobs.</p><form onSubmit={event => { event.preventDefault(); save.mutate(); }}><Field name="Discovery provider"><select aria-label="Discovery provider" value={provider} onChange={event => { setProvider(event.target.value); setRegion("global"); setBoard(""); setEmployer(""); setQuery(""); }}><option value="greenhouse">Greenhouse</option><option value="lever">Lever</option><option value="ashby">Ashby</option><option value="smartrecruiters">SmartRecruiters</option><option value="reed">Reed search</option></select></Field>{provider === "reed" ? <Field name="Reed search keywords"><input required maxLength={300} value={query} onChange={event => setQuery(event.target.value)} placeholder="graduate software engineer" /></Field> : <><Field name={provider === "lever" ? "Lever board slug" : provider === "ashby" ? "Ashby board slug" : provider === "smartrecruiters" ? "SmartRecruiters company identifier" : "Greenhouse board slug"}><input required pattern="[A-Za-z0-9_-]{1,100}" maxLength={100} value={board} onChange={event => setBoard(event.target.value)} placeholder="Employer board identifier, not a URL" /></Field><Field name="Employer name on the board"><input required={provider !== "greenhouse"} maxLength={200} value={employer} onChange={event => setEmployer(event.target.value)} placeholder={provider !== "greenhouse" ? "Required: exact employer name" : "Optional fallback if API omits it"} /></Field></>}{provider === "reed" && <p className="small">Configure REED_API_KEY privately on the server before importing. No API key is entered in the browser.</p>}{provider === "lever" && <Field name="Lever region"><select aria-label="Lever region" value={region} onChange={event => setRegion(event.target.value)}><option value="global">Global — jobs.lever.co</option><option value="eu">EU — jobs.eu.lever.co</option></select></Field>}<label className="checkbox-label"><input type="checkbox" checked={enabled} onChange={event => setEnabled(event.target.checked)} />Enable this source for manual imports</label><Button type="submit" disabled={save.isPending}>Add discovery source</Button></form><p className="small">Review the source’s terms before enabling fetch access. Setup instructions cover the public API host permission. No automatic discovery runs are scheduled.</p><ErrorText error={sources.error ?? save.error ?? remove.error ?? run.error} />{sources.data?.map(source => <article className="fact-card" key={source.id}><strong>{source.employer || source.search_query || source.board}</strong><p className="small">{source.provider === "lever" ? `Lever · ${source.region.toUpperCase()}` : source.provider === "ashby" ? "Ashby" : source.provider === "smartrecruiters" ? "SmartRecruiters" : source.provider === "reed" ? "Reed search" : "Greenhouse"} · {source.search_query || source.board}</p><p className="small">{source.enabled ? "Enabled for manual imports" : "Disabled"}</p>{source.provider === "reed" && !source.credentials_configured && <p className="notice">Private Reed API key not configured.</p>}<div className="fact-actions"><Button variant="outline" disabled={!source.enabled || !source.credentials_configured || run.isPending} onClick={() => run.mutate(source.id)}>Discover jobs from {source.search_query || source.board}</Button><Button variant="ghost" disabled={remove.isPending} onClick={() => remove.mutate(source.id)}>Remove {source.search_query || source.board}</Button></div></article>)}</div></details>;
}


type Match = { score: number; stale: boolean; feedback: "good" | "bad" | null; breakdown: { criterion: string; points: number; maximum: number; explanation: string; fact_ids: string[] }[] };
export function PreferenceMatch({ jobId, ready, summaryOnly = false }: { jobId: string; ready: boolean; summaryOnly?: boolean }) {
  const client = useQueryClient();
  const [taskId, setTaskId] = useState<string | null>(null);
  const [taskError, setTaskError] = useState<string | null>(null);
  const result = useQuery({ queryKey: ["matches", jobId], queryFn: () => api<Match | null>(`jobs/${jobId}/match`), enabled: ready, staleTime: 0, refetchOnWindowFocus: true });
  const tasks = useQuery({ queryKey: ["matching-task", taskId], queryFn: () => api<Task[]>("tasks"), enabled: Boolean(taskId), refetchInterval: 1500 });
  const currentTask = tasks.data?.find(task => task.id === taskId);
  useEffect(() => {
    if (currentTask && ["SUCCEEDED", "FAILED", "NEEDS_INPUT"].includes(currentTask.status)) {
      void client.invalidateQueries({ queryKey: ["matches", jobId] });
      setTaskError(currentTask.status === "SUCCEEDED" ? null : currentTask.message ?? "Matching stopped. Check Background tasks.");
      setTaskId(null);
    }
  }, [client, currentTask, jobId]);
  const calculate = useMutation({ mutationFn: () => api<Task>("tasks/match", "POST", { job_id: jobId }), onSuccess: task => { setTaskError(null); setTaskId(task.id); } });
  const feedback = useMutation({ mutationFn: (value: "good" | "bad") => api(`jobs/${jobId}/feedback`, "POST", { value }), onSuccess: () => Promise.all([client.invalidateQueries({ queryKey: ["matches", jobId] }), client.invalidateQueries({ queryKey: ["match-feedback"] })]) });
  return <section className="panel"><h3>Preference match</h3>{summaryOnly && <p className="notice">Based on your Notes summary. Full vacancy requirements have not been extracted yet.</p>}<p className="small">A local heuristic for your preferences, not an eligibility decision or chance of success. Sponsorship does not affect the score.</p><ErrorText error={result.error ?? calculate.error ?? feedback.error ?? tasks.error} />{taskError && <p role="alert" className="error">{taskError}</p>}{result.data?.stale && <p role="status" className="notice">Job, reviewed facts or preferences changed. Recalculate before using the score.</p>}{!ready && <p className="notice">Add the role title and vacancy description, or paste the listing URL on Dashboard to fill missing imported details. Notes and statuses are preserved.</p>}{ready && result.data && !result.data.stale && <><p><strong>{result.data.score}/100</strong></p><details><summary>Why this score?</summary>{result.data.breakdown.map(item => <div className="fact-card" key={item.criterion}><strong>{item.criterion.replaceAll("_", " ")}: {item.points}/{item.maximum}</strong><p className="small">{item.explanation}</p>{item.fact_ids.length > 0 && <code className="fact-id">Reviewed facts: {item.fact_ids.join(", ")}</code>}</div>)}</details><div className="fact-actions"><Button variant="outline" disabled={feedback.isPending} onClick={() => feedback.mutate("good")}>Good match</Button><Button variant="outline" disabled={feedback.isPending} onClick={() => feedback.mutate("bad")}>Poor match</Button></div>{result.data.feedback && <p className="small" role="status">Rating saved: {result.data.feedback}. Ratings do not automatically change weights.</p>}</>}<div className="fact-actions"><Button disabled={!ready || calculate.isPending || Boolean(taskId)} onClick={() => calculate.mutate()}>{taskId ? "Calculating…" : "Calculate preference match"}</Button></div></section>;
}


export function JobSources({ jobId, snapshot, onSelect }: { jobId: string; snapshot: string; onSelect: (id: string) => void }) {
  const client = useQueryClient();
  const [url, setUrl] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const sources = useQuery({ queryKey: ["sources", jobId], queryFn: () => api<{ id: string; url: string; method: string }[]>(`jobs/${jobId}/sources`), staleTime: 0 });
  const duplicates = useQuery({ queryKey: ["duplicates", jobId], queryFn: () => api<{ id: string; title: string; company: string; location: string; similarity: number }[]>(`jobs/${jobId}/duplicates`), staleTime: 0 });
  const refresh = () => Promise.all([client.invalidateQueries({ queryKey: ["sources", jobId] }), client.invalidateQueries({ queryKey: ["duplicates", jobId] })]);
  const link = useMutation({ mutationFn: () => api(`jobs/${jobId}/sources`, "POST", { url, snapshot, confirmed }), onSuccess: async () => { setUrl(""); setConfirmed(false); await refresh(); } });
  const unlink = useMutation({ mutationFn: (sourceId: string) => api(`jobs/${jobId}/sources/${sourceId}`, "DELETE", { snapshot, confirmed: true }), onSuccess: async () => { link.reset(); await refresh(); } });
  const pending = link.isPending || unlink.isPending;
  return <section className="panel"><h3>Sources and possible duplicates</h3><p className="small">Known posting IDs keep repeat discoveries together. Similar titles are review hints; existing jobs and histories are never merged automatically.</p><ErrorText error={sources.error ?? duplicates.error ?? link.error ?? unlink.error} />
    {sources.data?.map(source => <div className="fact-card" key={source.id}><a className="button button-ghost fact-id" href={source.url} target="_blank" rel="noopener noreferrer">{source.url}</a><p className="small">{source.method === "owner_confirmed" ? "Reviewed by you" : source.method === "ats_id" ? "Same posting ID" : "Saved listing"}</p>{source.method === "owner_confirmed" && <Button variant="ghost" disabled={pending} onClick={() => { if (window.confirm("Remove this reviewed secondary link? The job and application history stay saved. Previously imported content is retained.")) unlink.mutate(source.id); }}>Remove reviewed link</Button>}</div>)}
    <details><summary>Link another listing for this vacancy</summary><p className="small">Read both listings first. Add a second URL only if it is the same vacancy. Future imports of that URL reuse this job and its history. A URL already saved on another job must be reviewed separately; this does not merge existing records.</p><form onSubmit={event => { event.preventDefault(); if (confirmed && url.trim()) link.mutate(); }}><Field name="Additional listing URL"><input type="url" required maxLength={2048} value={url} onChange={event => { setUrl(event.target.value); setConfirmed(false); link.reset(); unlink.reset(); }} /></Field><label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => { setConfirmed(event.target.checked); link.reset(); }} />I checked that this is the same vacancy, not just a similar role or company page.</label><Button type="submit" disabled={!confirmed || !url.trim() || pending}>Link reviewed listing</Button></form></details>
    {link.isSuccess && <p className="small" role="status">Listing linked. Future imports reuse this job.</p>}{unlink.isSuccess && <p className="small" role="status">Secondary link removed. Job and history retained.</p>}
    {duplicates.data?.map(other => <div className="fact-card" key={other.id}><strong>{other.title}</strong><p className="small">{other.company} · {other.location} · {Math.round(other.similarity * 100)}% title similarity</p><Button variant="outline" onClick={() => onSelect(other.id)}>Review possible duplicate</Button></div>)}{duplicates.data?.length === 0 && <p className="small">No close-title duplicate candidates found.</p>}</section>;
}


function MatchingPreferences({ data }: { data: Settings }) {
  const client = useQueryClient();
  const [roles, setRoles] = useState(data.target_roles.join(", "));
  const [weights, setWeights] = useState(data.weights);
  useEffect(() => { setRoles(data.target_roles.join(", ")); setWeights(data.weights); }, [data.target_roles, data.weights]);
  const names: Record<string, string> = { role: "Role preference", graduate: "Graduate/junior level", location: "Location", skills: "Reviewed skills", experience: "Reviewed experience", start_date: "Start year" };
  const total = Object.values(weights).reduce((sum, value) => sum + value, 0);
  const keywords = roles.split(",").map(value => value.trim()).filter(Boolean);
  const valid = Object.keys(weights).length === 6 && total === 100 && Object.values(weights).every(value => Number.isInteger(value) && value >= 0 && value <= 100) && keywords.length <= 30 && keywords.every(value => value.length <= 200);
  const ratings = useQuery({ queryKey: ["match-feedback"], queryFn: () => api<{ good: number; bad: number; stale: number }>("matches/feedback"), staleTime: 0 });
  const save = useMutation({ mutationFn: () => api("settings", "PUT", { ...data, target_roles: keywords, weights }), onSuccess: () => Promise.all([client.invalidateQueries({ queryKey: ["settings"] }), client.invalidateQueries({ queryKey: ["matches"] }), client.invalidateQueries({ queryKey: ["match-feedback"] })]) });
  return <details className="panel disclosure"><summary>Matching preferences<span className="summary-hint">Your priorities · Local scores</span></summary><div className="disclosure-content"><p className="small">Adjust what matters to you. Sponsorship has no score weight. Changing preferences makes previous scores stale; use Score active jobs afterwards.</p><form onSubmit={event => { event.preventDefault(); if (valid) save.mutate(); }}><Field name="Preferred role keywords"><input maxLength={2000} value={roles} onChange={event => { setRoles(event.target.value); save.reset(); }} placeholder="software engineer, data, technology" /></Field><p className="small">Up to 30 comma-separated keywords or phrases, 200 characters each. Blank uses the default technology terms. These prioritise titles; they do not exclude other jobs.</p><div className="form-grid">{Object.entries(weights).map(([key, value]) => <Field key={key} name={`${names[key] ?? key} weight`}><input type="number" min={0} max={100} step={1} value={value} onChange={event => { setWeights({ ...weights, [key]: Number.isFinite(event.target.valueAsNumber) ? event.target.valueAsNumber : 0 }); save.reset(); }} /></Field>)}</div><p className={valid ? "small" : "error"} role="status">Weight total: {total}/100. {valid ? "Ready to save." : "Use whole numbers from 0 to 100, totalling 100, and valid keywords."}</p><ErrorText error={save.error ?? ratings.error} />{save.isSuccess && <p className="success" role="status">Matching preferences saved. Recalculate changed scores.</p>}<Button type="submit" disabled={!valid || save.isPending}>Save matching preferences</Button></form>{ratings.data && <p className="small" role="status">Current-score ratings: {ratings.data.good} good · {ratings.data.bad} poor · {ratings.data.stale} on changed inputs. Ratings guide manual adjustments; no automatic training. Changed-score calculations need a new rating.</p>}</div></details>;
}


type SponsorshipEvidence = { status: "UNVERIFIED" | "CONFIRMED_YES" | "CONFIRMED_NO"; evidence_quote: string | null; source_url: string | null; reviewed_at: string | null; stale: boolean; snapshot: string };
export function SponsorshipReview({ jobId, snapshot }: { jobId: string; snapshot: string }) {
  const client = useQueryClient();
  const review = useQuery({ queryKey: ["sponsorship", jobId, snapshot], queryFn: () => api<SponsorshipEvidence>(`jobs/${jobId}/eligibility`), staleTime: 0 });
  const sources = useQuery({ queryKey: ["sources", jobId], queryFn: () => api<{ url: string }[]>(`jobs/${jobId}/sources`) });
  const [status, setStatus] = useState("");
  const [quote, setQuote] = useState("");
  const [source, setSource] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const [reviewedSnapshot, setReviewedSnapshot] = useState("");
  const refresh = () => Promise.all([client.invalidateQueries({ queryKey: ["sponsorship", jobId] }), client.invalidateQueries({ queryKey: ["jobs"] })]);
  const save = useMutation({ mutationFn: () => api(`jobs/${jobId}/eligibility`, "PUT", { status, evidence_quote: quote, source_url: source, snapshot: reviewedSnapshot, confirmed }), onSuccess: async () => { setConfirmed(false); await refresh(); } });
  const clear = useMutation({ mutationFn: () => api(`jobs/${jobId}/eligibility`, "DELETE"), onSuccess: async () => { setConfirmed(false); save.reset(); await refresh(); } });
  const current = review.data;
  return <section className="panel" aria-label="Sponsorship evidence"><h3>Sponsorship</h3><span className="badge unverified">{current?.status === "CONFIRMED_YES" ? "Confirmed" : current?.status === "CONFIRMED_NO" ? "Not offered" : "Unverified"}</span><p className="small muted">Informational only; never changes your preference score or legal declarations. A sponsor licence is a separate signal; see the register check below.</p>{current?.stale && <p className="notice" role="status">Vacancy content changed. Previous evidence needs a fresh review; status is Unverified.</p>}{current?.evidence_quote && <><blockquote className="preserve">{current.evidence_quote}</blockquote><p><a href={current.source_url ?? undefined} target="_blank" rel="noopener noreferrer">Open evidence source</a></p><p className="small">{current.stale ? "Previous review" : "Reviewed by you"}: {current.reviewed_at ? new Date(current.reviewed_at).toLocaleString("en-GB", { timeZone: "Europe/London" }) : "Unknown"}</p><Button variant="outline" disabled={clear.isPending} onClick={() => clear.mutate()}>Clear sponsorship review</Button></>}<details><summary>Review role-specific evidence</summary><p className="small">Read the listing and quote its complete explicit sponsorship statement, including conditions. Notes, historic company behaviour and licences are insufficient. If uncertain, leave Unverified. The app checks the quote belongs to saved vacancy text; you judge its meaning.</p><form onSubmit={event => { event.preventDefault(); if (confirmed && current) save.mutate(); }}><Field name="Sponsorship finding"><select aria-label="Sponsorship finding" required value={status} onChange={event => { setStatus(event.target.value); setConfirmed(false); save.reset(); }}><option value="">Choose an explicit finding</option><option value="CONFIRMED_YES">Explicitly offered for this role</option><option value="CONFIRMED_NO">Explicitly not offered for this role</option></select></Field><Field name="Exact sponsorship quote"><textarea required minLength={10} maxLength={5000} rows={4} value={quote} onChange={event => { setQuote(event.target.value); setConfirmed(false); save.reset(); }} /></Field><Field name="Evidence listing source"><select aria-label="Evidence listing source" required value={source} onChange={event => { setSource(event.target.value); setConfirmed(false); save.reset(); }}><option value="">Choose the listing you reviewed</option>{sources.data?.map(item => <option key={item.url} value={item.url}>{item.url}</option>)}</select></Field><label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => { setConfirmed(event.target.checked); setReviewedSnapshot(current?.snapshot ?? ""); }} />I reviewed the full role statement and its conditions; it explicitly supports this finding.</label><Button type="submit" disabled={!status || !confirmed || !quote.trim() || !source || !current || reviewedSnapshot !== current.snapshot || save.isPending}>Save sponsorship evidence</Button></form></details><ErrorText error={review.error ?? sources.error ?? save.error ?? clear.error} />{save.isSuccess && <p className="small" role="status">Evidence review saved.</p>}</section>;
}


type RequirementTerm = { value: string; quote: string };
type SourceAnalysis = { configured: boolean; has_description: boolean; state: "not_extracted" | "current" | "stale"; data: { skills: RequirementTerm[]; education: RequirementTerm[]; experience: RequirementTerm[] } | null; model: string | null; source_chars: number | null; truncated: boolean };
export function SourceRequirements({ jobId, snapshot }: { jobId: string; snapshot: string }) {
  const client = useQueryClient();
  const [taskId, setTaskId] = useState<string | null>(null);
  const [taskError, setTaskError] = useState<string | null>(null);
  const result = useQuery({ queryKey: ["requirements", jobId, snapshot], queryFn: () => api<SourceAnalysis>(`jobs/${jobId}/requirements`), staleTime: 0 });
  const tasks = useQuery({ queryKey: ["requirements-task", taskId], queryFn: () => api<Task[]>("tasks"), enabled: Boolean(taskId), refetchInterval: 1500 });
  const currentTask = tasks.data?.find(task => task.id === taskId);
  useEffect(() => {
    if (currentTask && ["SUCCEEDED", "FAILED", "NEEDS_INPUT"].includes(currentTask.status)) {
      for (const key of ["requirements", "matches", "tasks"]) void client.invalidateQueries({ queryKey: [key] });
      setTaskError(currentTask.status === "SUCCEEDED" ? null : currentTask.message ?? "Local extraction stopped. Check Background tasks.");
      setTaskId(null);
    }
  }, [client, currentTask]);
  const run = useMutation({ mutationFn: () => api<Task>("tasks/requirements", "POST", { job_id: jobId }), onSuccess: task => { setTaskError(null); setTaskId(task.id); } });
  const data = result.data;
  return <section className="panel" aria-label="Source requirements"><h3>Source requirements</h3><p className="small">Extract technology, education and experience terms locally. Quotes must match the vacancy. These are source-grounded candidates, not an eligibility decision. Your Notes, CV facts and legal answers are excluded.</p>{!data?.configured && !result.isPending && <p className="notice">Local Ollama extraction is not configured. Follow the Ollama setup instructions first.</p>}{data && !data.has_description && <p className="notice">Add the original vacancy description first. Notes summaries are not sent to the model.</p>}{data?.state === "stale" && <p className="notice" role="status">Vacancy changed. Old extracted requirements are not used; extract again.</p>}{data?.state === "current" && <><p className="small">Extracted with {data.model}. Recalculate the preference score after extraction. Quotes show where each candidate came from; check their meaning.</p>{data.truncated && <p className="notice">Only the first {data.source_chars} characters were analysed; later requirements may be missing.</p>}<details><summary>View extracted terms and quotes</summary>{Object.entries(data.data ?? {}).map(([kind, terms]) => <div key={kind}><h4>{kind[0].toUpperCase() + kind.slice(1)}</h4>{terms.length ? terms.map(term => <div className="fact-card" key={term.value}><strong>{term.value}</strong><blockquote className="preserve">{term.quote}</blockquote></div>) : <p className="small">No terms extracted. This does not prove the vacancy has none.</p>}</div>)}</details></>}<ErrorText error={result.error ?? run.error ?? tasks.error} />{taskError && <p className="error" role="alert">{taskError}</p>}<Button disabled={!data?.configured || !data.has_description || run.isPending || Boolean(taskId)} onClick={() => run.mutate()}>{taskId ? "Extracting locally…" : "Extract requirements locally"}</Button></section>;
}


type RegisterSnapshot = { source_url: string; as_of: string; sha256: string; rows_read: number; organisations: number; imported_at: string; verification: string };
function SponsorRegisterSettings() {
  const client = useQueryClient();
  const registry = useQuery({ queryKey: ["sponsor-register"], queryFn: () => api<RegisterSnapshot | null>("sponsors/register") });
  const [file, setFile] = useState<File | null>(null);
  const [source, setSource] = useState("");
  const [date, setDate] = useState("");
  const [organisationHeader, setOrganisationHeader] = useState("Organisation Name");
  const [routeHeader, setRouteHeader] = useState("Route");
  const [townHeader, setTownHeader] = useState("Town/City");
  const [confirmed, setConfirmed] = useState(false);
  const upload = useMutation({ mutationFn: async () => {
    if (!file || file.size > 50_000_000) throw new Error("Choose a register CSV under 50 MB.");
    const metadata = JSON.stringify({ source_url: source, as_of: date, organisation_header: organisationHeader, route_header: routeHeader, town_header: townHeader, confirmed }).replace(/[\u007f-\uffff]/g, char => `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`);
    const response = await fetch("/api/sponsors/register", { method: "POST", headers: { "Content-Type": "text/csv", "X-Register-Metadata": metadata }, body: file });
    if (!response.ok) { const error = await response.json().catch(() => ({})); throw new Error(typeof error.detail === "string" ? error.detail : "Register upload failed; check file size and metadata."); }
    return response.json() as Promise<Task>;
  }, onSuccess: () => { setConfirmed(false); return client.invalidateQueries({ queryKey: ["tasks"] }); } });
  return <details className="panel disclosure"><summary>Sponsor register<span className="summary-hint">Separate dated name-match signal</span></summary><div className="disclosure-content"><p className="small">Import the Home Office worker sponsor CSV. An organisation-name match is informational; role sponsorship still needs its own evidence and never changes your score.</p><p><a href="https://www.gov.uk/government/publications/register-of-licensed-sponsors-workers" target="_blank" rel="noopener noreferrer">Get the official register</a></p>{registry.data && <p className="notice">Current file: {registry.data.as_of} · {registry.data.organisations} organisations · owner-confirmed upload.</p>}<form onSubmit={event => { event.preventDefault(); if (confirmed) upload.mutate(); }}><Field name="Sponsor register CSV"><input type="file" accept=".csv,text/csv" required onChange={event => { setFile(event.target.files?.[0] ?? null); setConfirmed(false); upload.reset(); }} /></Field><Field name="Official register CSV URL"><input type="url" required maxLength={2048} value={source} onChange={event => { setSource(event.target.value); setConfirmed(false); }} placeholder="https://assets.publishing.service.gov.uk/media/…/register.csv" /></Field><Field name="Register publication date"><input type="date" required value={date} onChange={event => { setDate(event.target.value); setConfirmed(false); }} /></Field><details><summary>CSV column names</summary><p className="small">Check these against your downloaded file. Leave Town/City blank if absent.</p><Field name="Organisation column"><input required maxLength={200} value={organisationHeader} onChange={event => { setOrganisationHeader(event.target.value); setConfirmed(false); }} /></Field><Field name="Route column"><input required maxLength={200} value={routeHeader} onChange={event => { setRouteHeader(event.target.value); setConfirmed(false); }} /></Field><Field name="Town column"><input maxLength={200} value={townHeader} onChange={event => { setTownHeader(event.target.value); setConfirmed(false); }} /></Field></details><label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} />I downloaded this worker register from the official source and checked its date and column names.</label><Button type="submit" disabled={!file || !source || !date || !confirmed || upload.isPending}>Import sponsor register</Button></form><ErrorText error={registry.error ?? upload.error} />{upload.isSuccess && <p className="small" role="status">Register import queued. Check Background tasks; the previous snapshot stays active until validation succeeds.</p>}</div></details>;
}

export function SponsorRegisterSignal({ jobId, company }: { jobId: string; company: string }) {
  const result = useQuery({ queryKey: ["sponsor-register", jobId, company], queryFn: () => api<{ match: boolean | null; organisation: { name: string; routes: string[]; towns: string[] } | null; register: RegisterSnapshot | null }>(`jobs/${jobId}/sponsor-register`), staleTime: 0 });
  const data = result.data;
  return <section className="panel" aria-label="Sponsor register signal"><h3>Sponsor register</h3><p className="small">A dated organisation-name check, separate from this role’s sponsorship policy and your legal eligibility. It has no score weight.</p>{!result.isPending && data?.match === null && <p className="small">Not checked. Import a dated register CSV in Settings.</p>}{data?.register && <><p><strong>{data.match ? "Exact name found in imported register" : "No exact name match"}</strong></p>{!data.match && <p className="small">Brand and legal names can differ. Check the employer’s registered organisation name.</p>}{data.organisation && <><p>{data.organisation.name}</p><p className="small">Routes: {data.organisation.routes.join(", ")}</p><p className="small">Towns: {data.organisation.towns.join(", ") || "Not provided"}</p></>}<p className="small">Register date: {data.register.as_of}. Owner-confirmed upload; register contents may have changed since this date.</p><a href={data.register.source_url} target="_blank" rel="noopener noreferrer">Open imported CSV source</a><details><summary>Snapshot provenance</summary><p className="fact-id">SHA-256: {data.register.sha256}</p><p className="small">{data.register.organisations} organisation names · {data.register.rows_read} CSV rows. Name matching alone does not establish the role’s policy.</p></details></>}<ErrorText error={result.error} /></section>;
}
